'use strict';
const $=id=>document.getElementById(id);
let papers=[],loadError=false,controls=null,scanSession=0;
function navigate(url){document.body.classList.add('page-leaving');setTimeout(()=>location.href=url,170)}
function parseBarcode(raw){const v=raw.toUpperCase().replace(/[\s*]/g,'');const m=/^(P\d{5,7}[A-Z]{1,3})(\d*)$/.exec(v);if(!m)return null;const suffix=m[2];if(!suffix)return {code:m[1],page:null,total:null};if(suffix.length<3)return null;const page=Number.parseInt(suffix.slice(0,-2),10),total=Number.parseInt(suffix.slice(-2),10);return page>0&&page<=total?{code:m[1],page,total}:null}
function normalize(raw){return parseBarcode(raw)?.code||null}
const loaded=fetch('papers.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(d=>{papers=d.papers;const subjects=d.subjects||[];$('coverage').textContent=`已收录 ${papers.length} 份 IGCSE / IAL 试卷，覆盖 ${subjects.length} 个科目。索引更新：${d.updated}。`;$('subjectList').textContent=`支持科目：${subjects.join('、')}`;}).catch(()=>{loadError=true;$('coverage').textContent='索引暂时无法载入，请联网后刷新。';});
async function lookup(raw){await loaded;const barcode=parseBarcode(raw),code=barcode?.code;if(!code){$('status').textContent='请输入完整条码，例如 P76186A0628。';return}const cleaned=raw.toUpperCase().replace(/[\s*]/g,'');$('code').value=cleaned;if(loadError){$('status').textContent='索引未能载入，请联网后刷新。';return}const p=papers.find(x=>x.code===code);if(!p){$('status').textContent=`暂未收录 ${code}；可到 PaperLords 或 Pearson 目录查询。`;return}stop();$('scanner').classList.add('matched');$('status').textContent='识别成功，正在打开试卷…';setTimeout(()=>navigate(`result.html?barcode=${encodeURIComponent(cleaned)}`),280)}
function stop(){scanSession++;controls?.stop();controls=null;const stream=$('video').srcObject;stream?.getTracks().forEach(t=>t.stop());$('video').srcObject=null;$('scanner').classList.remove('active','matched');$('scan').hidden=false;$('scan').disabled=false;$('stop').hidden=true;$('cameraHint').textContent='将页面底部的完整条码放入框内'}
function closeScan(){stop();const url=new URL(location.href);if(url.searchParams.has('scan')){url.searchParams.delete('scan');history.replaceState(null,'',url)}}
async function startScan(){stop();const session=scanSession;$('scanner').classList.add('active');$('scan').hidden=true;$('stop').hidden=false;$('status').textContent='正在打开相机…';try{if(!navigator.mediaDevices?.getUserMedia||!window.ZXingBrowser)throw Error();const reader=new ZXingBrowser.BrowserMultiFormatOneDReader(new Map([[3,true]]));const c=await reader.decodeFromConstraints({audio:false,video:{facingMode:{ideal:'environment'},width:{ideal:1920},height:{ideal:1080}}},$('video'),(result,error,c)=>{if(session!==scanSession){c?.stop();return}if(result){const text=result.getText();if(normalize(text)){c?.stop();stop();lookup(text)}else $('status').textContent='已识别条码，但不是试卷编号；请对准 P 开头的条码。'}});if(session!==scanSession){c.stop();return}controls=c;$('status').textContent='扫描中。将完整条码放入框内。'}catch(e){stop();$('status').textContent=e.name==='NotAllowedError'?'相机权限未开启。请在 Safari 设置中允许相机。':'无法启动相机；可从照片识别或手动输入。'}}
$('lookup').addEventListener('submit',e=>{e.preventDefault();lookup($('code').value)});$('example').onclick=()=>lookup('P76186A0628');$('scan').onclick=startScan;$('stop').onclick=closeScan;
$('photo').onchange=async e=>{stop();const file=e.target.files[0];if(!file)return;$('status').textContent='正在识别照片…';const url=URL.createObjectURL(file);try{const r=await new ZXingBrowser.BrowserMultiFormatOneDReader(new Map([[3,true]])).decodeFromImageUrl(url);await lookup(r.getText())}catch{$('status').textContent='没有识别到清晰条码。请裁剪到条码附近，或手动输入。'}finally{URL.revokeObjectURL(url);e.target.value=''}};
document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});window.addEventListener('pagehide',stop);$('install').onclick=()=>$('installDialog').showModal();if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});if(new URLSearchParams(location.search).get('scan')==='1')setTimeout(startScan,100);
